<?= view('layout/header', ['title' => 'Record Sale']) ?><h1>Record sale</h1><div class="panel"><form method="post" action="<?= site_url('sales') ?>"><?= csrf_field() ?><label for="product">Product</label><select id="product" name="product_id" required><option value="">Select product</option><?php foreach ($products as $p): ?><option value="<?= esc($p['id'], 'attr') ?>" <?= (string)old('product_id') === (string)$p['id'] ? 'selected' : '' ?>><?= esc($p['name']) ?> — ₱<?= number_format((float)$p['price'], 2) ?> (<?= esc($p['stock_quantity']) ?> in stock)</option><?php endforeach ?></select><label for="customer">Customer (optional)</label><select id="customer" name="customer_id"><option value="">Walk-in customer</option><?php foreach ($customers as $c): ?><option value="<?= esc($c['id'], 'attr') ?>" <?= (string)old('customer_id') === (string)$c['id'] ? 'selected' : '' ?>><?= esc($c['full_name']) ?></option><?php endforeach ?></select><label for="quantity">Quantity</label><input id="quantity" name="quantity" type="number" min="1" max="2147483647" step="1" required value="<?= esc(old('quantity', 1), 'attr') ?>"><p><button>Record sale</button></p></form></div><?= view('layout/footer') ?>
